// Helper: Get today's date string (YYYY-MM-DD)
function getTodayDateString() {
    return formatDateString(new Date());
}

function formatDateString(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

const escapeXml = escapeHtml;

// Arabic text normalization helper for smart search (handles hamza, taa marbuta, alef maksura, tashkeel, spaces)
function normalizeArabicText(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/[\u064B-\u065F\u0670]/g, '') // remove tashkeel/harakat
        .replace(/[أإآء]/g, 'ا')              // normalize Alef variations
        .replace(/ة/g, 'ه')                   // normalize Taa marbuta
        .replace(/ى/g, 'ي')                   // normalize Alef maksura
        .replace(/[\u200B-\u200D\uFEFF]/g, '')// remove zero-width chars
        .replace(/\s+/g, ' ')                 // normalize whitespace
        .trim()
        .toLowerCase();
}

function matchArabicSearch(target, query) {
    if (!query || !query.trim()) return true;
    if (!target) return false;
    const normTarget = normalizeArabicText(target);
    const normQuery = normalizeArabicText(query);
    if (normTarget.includes(normQuery)) return true;
    
    // Also match without spaces (e.g. 'عبدالله' vs 'عبد الله')
    const targetNoSpace = normTarget.replace(/\s+/g, '');
    const queryNoSpace = normQuery.replace(/\s+/g, '');
    if (targetNoSpace.includes(queryNoSpace)) return true;
    
    // Also match individual word tokens (e.g. searching 'محمد عزام')
    const words = normQuery.split(' ').filter(w => w.length > 0);
    if (words.length > 1) {
        return words.every(w => normTarget.includes(w));
    }
    return false;
}

// ----------------- High-Grade Security & Authentication Management -----------------
function getAuthStorage(key) {
    return sessionStorage.getItem(key) || localStorage.getItem(key);
}

function setAuthStorage(key, value, rememberMe) {
    if (rememberMe) {
        localStorage.setItem(key, value);
    } else {
        sessionStorage.setItem(key, value);
    }
}

function clearAllAuthStorage() {
    ['token', 'role', 'userId', 'teacherId', 'studentId', 'parentId', 'fullName', 'username', 'loginTime', 'taskRole', 'mosqueName', 'qualification', 'hasChildren', 'childrenCount'].forEach(k => {
        sessionStorage.removeItem(k);
        localStorage.removeItem(k);
    });
}

function getToken() {
    return authToken || getAuthStorage("token") || "";
}
window.getToken = getToken;

function showConfirmModal(message, title = "تأكيد الإجراء") {
    return new Promise((resolve) => {
        if (typeof Swal !== "undefined") {
            Swal.fire({
                title: title,
                text: message,
                icon: "warning",
                showCancelButton: true,
                confirmButtonColor: "#0d5c3a",
                cancelButtonColor: "#64748b",
                confirmButtonText: "نعم، متأكد وموافق",
                cancelButtonText: "إلغاء التراجع",
                reverseButtons: true
            }).then((res) => resolve(res.isConfirmed));
        } else {
            resolve(window.confirm(message));
        }
    });
}
window.showConfirmModal = showConfirmModal;

function showLoading(msg = "جاري معالجة الطلب...") {
    let loader = document.getElementById("global-system-loading-modal");
    if (!loader) {
        loader = document.createElement("div");
        loader.id = "global-system-loading-modal";
        loader.style.cssText = "position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(15,23,42,0.65);backdrop-filter:blur(4px);z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;color:white;font-family:Cairo,sans-serif;";
        document.body.appendChild(loader);
    }
    loader.innerHTML = `
        <div style="background:#0f172a;padding:24px 32px;border-radius:16px;box-shadow:0 20px 40px rgba(0,0,0,0.5);text-align:center;border:1px solid rgba(255,255,255,0.1);max-width:90%;">
            <div class="spinner-border text-success mb-3" style="width: 3rem; height: 3rem;" role="status"></div>
            <div style="font-size:1.1rem;font-weight:700;">${escapeHtml(msg)}</div>
            <div style="font-size:0.85rem;color:#94a3b8;margin-top:6px;">يرجى الانتظار، جاري المزامنة مع المنظومة...</div>
        </div>
    `;
    loader.style.display = "flex";
}
window.showLoading = showLoading;

function hideLoading() {
    const loader = document.getElementById("global-system-loading-modal");
    if (loader) loader.style.display = "none";
}
window.hideLoading = hideLoading;

