// ----------------- Activation & Deactivation Handlers -----------------
async function toggleStudentActive(id) {
    try {
        const res = await apiRequest(`/students/${id}/toggle-active`, "POST");
        showAlert(res.message || "تم تحديث حالة الطالب بنجاح", "success");
        loadAdminStudents();
    } catch (e) {
        showAlert(e.message, "danger");
    }
}

async function toggleTeacherActive(id) {
    try {
        const res = await apiRequest(`/teachers/${id}/toggle-active`, "POST");
        showAlert(res.message || "تم تحديث حالة المعلم بنجاح", "success");
        loadAdminTeachers();
    } catch (e) {
        showAlert(e.message, "danger");
    }
}

async function toggleCircleActive(id) {
    try {
        const res = await apiRequest(`/circles/${id}/toggle-active`, "POST");
        showAlert(res.message || "تم تحديث حالة الحلقة بنجاح", "success");
        loadAdminCircles();
    } catch (e) {
        showAlert(e.message, "danger");
    }
}


// ----------------- Admin: Circles Management -----------------
async function loadAdminCircles() {
    try {
        const circles = await apiRequest("/circles");
        cachedCircles = circles || [];
        
        // Load teachers if not already loaded
        if (!cachedTeachers || cachedTeachers.length === 0) {
            cachedTeachers = await apiRequest("/teachers");
        }
        
        const tbody = document.getElementById("circles-table-body");
        if (!tbody) return;
        tbody.innerHTML = "";
        
        if (cachedCircles.length === 0) {
            tbody.innerHTML = `<tr><td colspan="8" class="text-center text-muted p-4">لا توجد حلقات مضافة حالياً.</td></tr>`;
            return;
        }
        
        cachedCircles.forEach((c, index) => {
            const tr = document.createElement("tr");
            const leadTeacher = c.teacherName ? `<strong class="text-success"><i class="fa-solid fa-user-tie me-1"></i> ${c.teacherName}</strong>` : '<span class="text-danger">غير معين</span>';
            const assistantTeacher = c.assistantTeacherName ? `<span class="badge bg-info bg-opacity-10 text-dark border border-info px-2 py-1"><i class="fa-solid fa-handshake-angle me-1 text-info"></i> ${c.assistantTeacherName}</span>` : '<span class="text-muted small">بدون مساعد</span>';

            tr.innerHTML = `
                <td class="text-center font-monospace fw-bold text-muted" style="width: 50px;">${index + 1}</td>
                <td>
                    <strong>${c.name}</strong>
                    <span class="badge bg-light text-secondary border font-monospace ms-1" title="معرف الحلقة في قاعدة البيانات" style="font-size: 0.72rem;">#${c.id}</span>
                </td>
                <td><span class="badge bg-light text-dark border">${getTimingArabic(c.timing)}</span></td>
                <td>${leadTeacher}</td>
                <td>${assistantTeacher}</td>
                <td><span class="badge bg-primary bg-opacity-10 text-primary font-monospace fw-bold">${c.studentCount} طلاب</span></td>
                <td>
                    <span class="badge ${c.isActive ? 'bg-success' : 'bg-danger'}">
                        ${c.isActive ? 'نشط' : 'معطّل'}
                    </span>
                </td>
                <td>
                    <div class="table-actions-nowrap">
                        <button class="btn btn-outline-primary btn-sm btn-edit-circle" data-id="${c.id}" title="تعديل"><i class="fa-solid fa-pen"></i> تعديل</button>
                        <button class="btn btn-light btn-sm border btn-manage-students" data-id="${c.id}" title="إدارة الطلاب"><i class="fa-solid fa-user-gear"></i> إدارة الطلاب</button>
                        <button class="btn ${c.isActive ? 'btn-outline-warning text-dark' : 'btn-outline-success'} btn-sm btn-toggle-circle" data-id="${c.id}" title="${c.isActive ? 'تعطيل' : 'تنشيط'}">
                            <i class="fa-solid ${c.isActive ? 'fa-ban' : 'fa-check'}"></i>
                        </button>
                        <button class="btn btn-outline-danger btn-sm btn-hard-delete-circle" data-id="${c.id}" data-name="${c.name}" title="حذف نهائي">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </td>
            `;
            tbody.appendChild(tr);
        });
        
        // Bind Actions
        document.querySelectorAll(".btn-edit-circle").forEach(btn => {
            btn.addEventListener("click", (e) => showCircleModal(e.target.closest("button").dataset.id));
        });
        document.querySelectorAll(".btn-manage-students").forEach(btn => {
            btn.addEventListener("click", (e) => showManageStudentsModal(e.target.closest("button").dataset.id));
        });
        document.querySelectorAll(".btn-toggle-circle").forEach(btn => {
            btn.addEventListener("click", (e) => toggleCircleActive(e.target.closest("button").dataset.id));
        });
        document.querySelectorAll(".btn-hard-delete-circle").forEach(btn => {
            btn.addEventListener("click", (e) => {
                const b = e.target.closest("button");
                hardDeleteCircle(b.dataset.id, b.dataset.name);
            });
        });

        const btnAddCircle = document.getElementById("btn-add-circle");
        if (btnAddCircle && !btnAddCircle._bound) {
            btnAddCircle._bound = true;
            btnAddCircle.addEventListener("click", () => showCircleModal());
        }
        
    } catch(e) {
        console.error(e);
    }
}

async function toggleCircleActive(id) {
    try {
        const res = await apiRequest(`/circles/${id}/toggle-active`, "POST");
        showAlert(res.message || "تم تحديث حالة الحلقة بنجاح", "success");
        loadAdminCircles();
    } catch (e) {
        showAlert(e.message, "danger");
    }
}

async function hardDeleteCircle(id, name) {
    const result = await Swal.fire({
        title: '⚠️ تأكيد حذف الحلقة القرآنية',
        html: `هل أنت متأكد من حذف حلقة <strong>${name}</strong> نهائياً وفك ارتباط الطلاب بها؟`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonText: 'نعم، حذف نهائي',
        cancelButtonText: 'تراجع',
        confirmButtonColor: '#d33'
    });

    if (result.isConfirmed) {
        try {
            const res = await apiRequest(`/circles/${id}/permanent`, 'DELETE');
            showAlert(res.message || "تم حذف الحلقة بنجاح.", "success");
            await loadAdminCircles();
        } catch(err) {
            showAlert(err.message || "حدث خطأ أثناء حذف الحلقة", "danger");
        }
    }
}

async function showCircleModal(circleId = null) {
    let circle = null;
    if (circleId) {
        circle = (cachedCircles || []).find(c => c.id == circleId);
        if (!circle) {
            try {
                circle = await apiRequest(`/circles/${circleId}`);
            } catch(e) {}
        }
    }

    if (!cachedTeachers || cachedTeachers.length === 0) {
        try {
            cachedTeachers = await apiRequest("/teachers");
        } catch(e) {
            cachedTeachers = [];
        }
    }

    const validTeachers = (cachedTeachers || []).filter(t => t.isActive);

    let teacherOptions = '<option value="">-- بدون معلم مشرف --</option>';
    let assistantOptions = '<option value="">-- بدون معلم مساعد (اختياري) --</option>';

    validTeachers.forEach(t => {
        const isTSelected = (circle && circle.teacherId == t.id) ? 'selected' : '';
        const isASelected = (circle && circle.assistantTeacherId == t.id) ? 'selected' : '';
        const displayRole = (t.taskRole && t.taskRole.trim()) ? t.taskRole : 'غير مكلف';
        teacherOptions += `<option value="${t.id}" ${isTSelected}>${t.fullName} (${displayRole})</option>`;
        assistantOptions += `<option value="${t.id}" ${isASelected}>${t.fullName} (${displayRole})</option>`;
    });

    const timingOptions = `
        <option value="Fajr" ${circle && circle.timing === 'Fajr' ? 'selected' : ''}>بعد الفجر</option>
        <option value="Aser" ${circle && circle.timing === 'Aser' ? 'selected' : ''}>بعد العصر</option>
        <option value="Maghrib" ${circle && circle.timing === 'Maghrib' ? 'selected' : ''}>بعد المغرب</option>
        <option value="Isha" ${circle && circle.timing === 'Isha' ? 'selected' : ''}>بعد العشاء</option>
    `;

    const htmlContent = `
        <div class="text-start" style="direction: rtl;">
            <div class="mb-3">
                <label class="form-label fw-bold"><i class="fa-solid fa-mosque text-success me-1"></i> اسم الحلقة القرآنية <span class="text-danger">*</span></label>
                <input id="swal-circle-name" class="form-control" placeholder="مثال: حلقة الفجر النموذجية / حلقة التميز" value="${circle ? (circle.name || '') : ''}">
            </div>
            <div class="mb-3">
                <label class="form-label fw-bold"><i class="fa-solid fa-clock text-primary me-1"></i> موعد ووقت الانعقاد <span class="text-danger">*</span></label>
                <select id="swal-circle-timing" class="form-select">
                    ${timingOptions}
                </select>
            </div>
            <div class="mb-3">
                <label class="form-label fw-bold"><i class="fa-solid fa-user-tie text-primary me-1"></i> المعلم والمحفّظ المشرف الرئيسي <span class="text-danger">*</span></label>
                <select id="swal-circle-teacher" class="form-select">
                    ${teacherOptions}
                </select>
                <div class="form-text text-muted">المعلم المسؤول الأول عن متابعة الحلقة.</div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-bold"><i class="fa-solid fa-handshake-angle text-info me-1"></i> مساعد الحلقة (المعلم المساعد) <span class="badge bg-light text-muted border">نفس الصلاحيات والحلقة</span></label>
                <select id="swal-circle-assistant" class="form-select">
                    ${assistantOptions}
                </select>
                <div class="form-text text-success"><i class="fa-solid fa-circle-check me-1"></i> يتمكن المساعد من رصد الحضور والتسميع لنفس طلاب الحلقة المشتركة.</div>
            </div>
        </div>
    `;

    const result = await Swal.fire({
        title: circleId ? '✏️ تعديل بيانات الحلقة القرآنية' : '➕ إضافة حلقة قرآنية جديدة',
        html: htmlContent,
        showCancelButton: true,
        confirmButtonText: '<i class="fa-solid fa-floppy-disk me-1"></i> حفظ وتثبيت الحلقة',
        cancelButtonText: 'إلغاء',
        confirmButtonColor: '#0d5c3a',
        width: '580px',
        focusConfirm: false,
        preConfirm: () => {
            const name = document.getElementById("swal-circle-name").value.trim();
            const timing = document.getElementById("swal-circle-timing").value;
            const teacherIdVal = document.getElementById("swal-circle-teacher").value;
            const assistantIdVal = document.getElementById("swal-circle-assistant").value;

            if (!name) {
                Swal.showValidationMessage("يرجى إدخال اسم الحلقة القرآنية.");
                return false;
            }

            return {
                name,
                timing,
                teacherId: teacherIdVal ? parseInt(teacherIdVal) : null,
                assistantTeacherId: assistantIdVal ? parseInt(assistantIdVal) : null,
                isActive: circle ? circle.isActive : true
            };
        }
    });

    if (result.isConfirmed && result.value) {
        try {
            if (circleId) {
                await apiRequest(`/circles/${circleId}`, 'PUT', result.value);
                showAlert("تم تعديل وتحديث بيانات الحلقة والمساعد بنجاح! ✨", "success");
            } else {
                await apiRequest('/circles', 'POST', result.value);
                showAlert("تمت إضافة الحلقة القرآنية وإسناد المشايخ بنجاح! 🎉", "success");
            }
            await loadAdminCircles();
        } catch(err) {
            showAlert(err.message || "حدث خطأ أثناء حفظ الحلقة", "danger");
        }
    }
}

async function showManageStudentsModal(circleId) {
    try {
        let circle = (cachedCircles || []).find(c => c.id == circleId);
        if (!circle) circle = await apiRequest(`/circles/${circleId}`);

        let allStudents = cachedStudents;
        if (!allStudents || allStudents.length === 0) {
            allStudents = await apiRequest("/students/all-for-enrollment").catch(() => apiRequest("/students"));
            cachedStudents = allStudents || [];
        }

        const circleStudents = (allStudents || []).filter(s => s.circleId == circleId);
        const availableStudents = (allStudents || []).filter(s => s.circleId != circleId);

        let studentRowsHtml = circleStudents.map((s, idx) => `
            <tr>
                <td class="text-center font-monospace">${idx + 1}</td>
                <td><strong>${s.fullName}</strong></td>
                <td>${s.studentIdentityNumber || '-'}</td>
                <td class="text-center">
                    <button class="btn btn-outline-danger btn-sm py-0 px-2" onclick="removeStudentFromCircleModal(${circleId}, ${s.id})">
                        <i class="fa-solid fa-user-minus"></i> إزالة
                    </button>
                </td>
            </tr>
        `).join("");

        if (!studentRowsHtml) {
            studentRowsHtml = '<tr><td colspan="4" class="text-center text-muted p-3">لا يوجد طلاب ملتحقون بهذه الحلقة حالياً.</td></tr>';
        }

        let studentOptions = '<option value="">-- اختر طالباً لإضافته للحلقة --</option>';
        availableStudents.forEach(s => {
            const circleLabel = s.circleName && s.circleName !== "غير مسند حلقة" ? ` - حلقة: ${s.circleName}` : ' - غير مسند';
            studentOptions += `<option value="${s.id}">${s.fullName} (${s.studentIdentityNumber || 'بدون هوية'}${circleLabel})</option>`;
        });

        const htmlContent = `
            <div class="text-start" style="direction: rtl; font-size: 0.92rem;">
                <div class="p-3 bg-light border rounded-3 mb-3 d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-0 fw-bold text-success"><i class="fa-solid fa-mosque me-1"></i> ${circle.name}</h6>
                        <small class="text-muted">المحفّظ المشرف: ${circle.teacherName || 'غير معين'} | المساعد: ${circle.assistantTeacherName || 'بدون مساعد'}</small>
                    </div>
                    <span class="badge bg-primary px-3 py-2 fs-6 font-monospace">${circleStudents.length} طلاب</span>
                </div>

                <div class="mb-3 p-3 border rounded-3 bg-white shadow-xs">
                    <label class="form-label fw-bold mb-1"><i class="fa-solid fa-user-plus text-success me-1"></i> إضافة طالب جديد للحلقة</label>
                    <div class="d-flex gap-2">
                        <select id="swal-add-student-select" class="form-select form-select-sm">
                            ${studentOptions}
                        </select>
                        <button type="button" class="btn btn-success btn-sm px-3 fw-bold flex-shrink-0" onclick="addStudentToCircleModal(${circleId})">
                            <i class="fa-solid fa-plus me-1"></i> تنسيب
                        </button>
                    </div>
                </div>

                <div class="table-responsive border rounded-3" style="max-height: 280px; overflow-y: auto;">
                    <table class="table table-sm table-hover align-middle mb-0">
                        <thead class="table-light sticky-top">
                            <tr>
                                <th class="text-center" style="width: 40px;">#</th>
                                <th>اسم الطالب</th>
                                <th>رقم الهوية</th>
                                <th class="text-center" style="width: 80px;">إجراء</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${studentRowsHtml}
                        </tbody>
                    </table>
                </div>
            </div>
        `;

        await Swal.fire({
            title: `👥 إدارة طلاب حلقة (${circle.name})`,
            html: htmlContent,
            showConfirmButton: false,
            showCloseButton: true,
            width: '680px'
        });

    } catch(err) {
        showAlert("تعذر فتح إدارة طلاب الحلقة", "danger");
    }
}

async function addStudentToCircleModal(circleId) {
    const select = document.getElementById("swal-add-student-select");
    if (!select || !select.value) {
        showAlert("يرجى اختيار طالب أولاً", "warning");
        return;
    }
    const studentId = parseInt(select.value);
    try {
        await apiRequest(`/circles/${circleId}/students`, 'POST', { studentId });
        showAlert("تمت إضافة الطالب للحلقة بنجاح! ✅", "success");
        cachedStudents = await apiRequest("/students");
        await loadAdminCircles();
        showManageStudentsModal(circleId);
    } catch(err) {
        showAlert(err.message || "حدث خطأ أثناء إضافة الطالب", "danger");
    }
}

async function removeStudentFromCircleModal(circleId, studentId) {
    try {
        await apiRequest(`/circles/${circleId}/students/${studentId}`, 'DELETE');
        showAlert("تمت إزالة الطالب من الحلقة بنجاح.", "info");
        cachedStudents = await apiRequest("/students");
        await loadAdminCircles();
        showManageStudentsModal(circleId);
    } catch(err) {
        showAlert(err.message || "حدث خطأ أثناء إزالة الطالب", "danger");
    }
}

function getTimingArabic(timing) {
    switch(timing) {
        case "Fajr": return "بعد الفجر";
        case "Aser": return "بعد العصر";
        case "Maghrib": return "بعد المغرب";
        case "Isha": return "بعد العشاء";
        default: return timing;
    }
}

// ----------------- Admin: Teachers Management -----------------
async function loadAdminTeachers(search = "") {
    try {
        const teachers = await apiRequest(`/teachers?search=${search}`);
        const validTeachers = (teachers || []).filter(t => t.identityNumber && t.identityNumber.trim() !== "");
        cachedTeachers = validTeachers;
        
        const tbody = document.getElementById("teachers-table-body");
        tbody.innerHTML = "";
        
        if (validTeachers.length === 0) {
            tbody.innerHTML = `<tr><td colspan="9" class="text-center text-muted">لا يوجد معلّمون يطابقون البحث.</td></tr>`;
            return;
        }
        
        validTeachers.forEach((t, idx) => {
            const tr = document.createElement("tr");
            
            const idBadge = t.identityNumber 
                ? `<div class="teacher-id-badge"><i class="fa-solid fa-id-card text-primary"></i> <span class="id-val">${t.identityNumber}</span></div>` 
                : '<span class="text-muted small">-</span>';

            const mosqueStr = t.mosqueName 
                ? `<span class="teacher-mosque-tag"><i class="fa-solid fa-mosque text-muted"></i> ${t.mosqueName}</span>` 
                : '';

            const phoneStr = t.contact 
                ? `<div class="teacher-contact-pill"><i class="fa-solid fa-phone text-muted"></i> <span class="phone-val">${t.contact}</span></div>` 
                : '';

            const waNumClean = (t.whatsappNumber || '').replace(/[^0-9]/g, '');
            const waStr = t.whatsappNumber 
                ? `<a href="https://wa.me/${waNumClean}" target="_blank" class="teacher-wa-link" title="مراسلة عبر واتساب"><i class="fa-brands fa-whatsapp"></i> <span class="phone-val">${t.whatsappNumber}</span></a>` 
                : '';

            const roleBadge = formatTeacherRolesHtml(t.taskRole);

            const qualStr = t.qualification 
                ? `<span class="text-dark fw-bold small">${t.qualification}</span>` 
                : '<span class="text-muted small">-</span>';

            const juzBadge = t.memorizedAjzaa 
                ? `<span class="teacher-juz-pill"><i class="fa-solid fa-book-quran text-warning"></i> ${t.memorizedAjzaa}</span>` 
                : '<span class="text-muted small">-</span>';

            tr.innerHTML = `
                <td class="text-center fw-bold text-muted" style="width: 50px;">${idx + 1}</td>
                <td>
                    <div class="teacher-name-cell">
                        <span class="teacher-title-text">${t.fullName}</span>
                        ${mosqueStr}
                    </div>
                </td>
                <td>${idBadge}</td>
                <td>
                    <div class="teacher-contact-stack">
                        ${phoneStr}
                        ${waStr}
                    </div>
                </td>
                <td>${roleBadge}</td>
                <td>${qualStr}</td>
                <td>${juzBadge}</td>
                <td class="text-center">
                    <span class="teacher-status-pill ${t.isActive ? 'teacher-status-active' : 'teacher-status-inactive'}">
                        ${t.isActive ? 'نشط' : 'معطّل'}
                    </span>
                </td>
                <td class="text-center" style="width: 175px;">
                    <div class="table-actions-nowrap justify-content-center">
                        <button class="btn btn-success btn-sm btn-manage-teacher-roles shadow-xs" data-id="${t.id}" title="تحديد الصلاحيات والمهام الإدارية"><i class="fa-solid fa-user-shield me-1"></i> الصلاحيات</button>
                        <button class="btn btn-outline-primary btn-sm btn-edit-teacher shadow-xs" data-id="${t.id}" title="تعديل كافة البيانات"><i class="fa-solid fa-pen"></i></button>
                        <button class="btn ${t.isActive ? 'btn-outline-warning text-dark' : 'btn-outline-success'} btn-sm btn-toggle-teacher shadow-xs" data-id="${t.id}" title="${t.isActive ? 'تعطيل' : 'تنشيط'}">
                            <i class="fa-solid ${t.isActive ? 'fa-ban' : 'fa-check'}"></i>
                        </button>
                        <button class="btn btn-outline-danger btn-sm btn-hard-delete-teacher shadow-xs" data-id="${t.id}" data-name="${t.fullName}" title="حذف نهائي">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </td>
            `;
            tbody.appendChild(tr);
        });
        
        // Bind Actions
        document.querySelectorAll(".btn-manage-teacher-roles").forEach(btn => {
            btn.addEventListener("click", (e) => manageTeacherRoles(e.target.closest("button").dataset.id));
        });
        document.querySelectorAll(".btn-edit-teacher").forEach(btn => {
            btn.addEventListener("click", (e) => showTeacherModal(e.target.closest("button").dataset.id));
        });
        document.querySelectorAll(".btn-toggle-teacher").forEach(btn => {
            btn.addEventListener("click", (e) => toggleTeacherActive(e.target.closest("button").dataset.id));
        });
        document.querySelectorAll(".btn-hard-delete-teacher").forEach(btn => {
            btn.addEventListener("click", (e) => {
                const b = e.target.closest("button");
                hardDeleteTeacher(b.dataset.id, b.dataset.name);
            });
        });

        const btnAddTeacher = document.getElementById("btn-add-teacher");
        if (btnAddTeacher && !btnAddTeacher._bound) {
            btnAddTeacher._bound = true;
            btnAddTeacher.addEventListener("click", () => showTeacherModal());
        }

        const btnImportExcel = document.getElementById("btn-import-teachers-excel");
        if (btnImportExcel && !btnImportExcel._bound) {
            btnImportExcel._bound = true;
            btnImportExcel.addEventListener("click", async () => {
                let confirmed = false;
                if (typeof Swal !== 'undefined') {
                    const result = await Swal.fire({
                        title: 'استيراد كادر المعلمين (29-8)',
                        text: 'هل ترغب في استيراد وتحديث كافة المعلمين (35 معلماً) مع حسابات الدخول (رقم الهوية) والحلقات؟',
                        icon: 'question',
                        showCancelButton: true,
                        confirmButtonText: 'نعم، استيراد وتحديث الآن',
                        cancelButtonText: 'إلغاء',
                        confirmButtonColor: '#0d5c3a'
                    });
                    confirmed = result.isConfirmed;
                } else {
                    confirmed = confirm('هل ترغب في استيراد كادر المعلمين وتحديث بياناتهم؟');
                }

                if (!confirmed) return;

                try {
                    btnImportExcel.disabled = true;
                    btnImportExcel.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-1"></i> جاري الاستيراد...';
                    const res = await apiRequest('/teachers/import-excel', 'POST');
                    showAlert(res.message || 'تم استيراد كادر المعلمين بنجاح!', 'success');
                    await loadAdminTeachers();
                } catch(err) {
                    showAlert(err.message || 'حدث خطأ أثناء استيراد البيانات', 'danger');
                } finally {
                    btnImportExcel.disabled = false;
                    btnImportExcel.innerHTML = '<i class="fa-solid fa-file-excel me-1"></i> استيراد كادر المعلمين (29-8)';
                }
            });
        }

        const searchInput = document.getElementById("teacher-search-input");
        if (searchInput && !searchInput._bound) {
            searchInput._bound = true;
            searchInput.addEventListener("input", (e) => {
                loadAdminTeachers(e.target.value.trim());
            });
        }
        
    } catch(e) {
        console.error(e);
    }
}

async function toggleTeacherActive(id) {
    try {
        const res = await apiRequest(`/teachers/${id}/toggle-active`, 'POST');
        showAlert(res.message || "تم تغيير حالة المعلم بنجاح.", "success");
        await loadAdminTeachers();
    } catch(err) {
        showAlert(err.message || "حدث خطأ أثناء تغيير حالة المعلم", "danger");
    }
}

async function hardDeleteTeacher(id, name) {
    let confirmed = false;
    if (typeof Swal !== 'undefined') {
        const result = await Swal.fire({
            title: '⚠️ تأكيد الحذف النهائي للمعلم',
            html: `هل أنت متأكد من حذف الشيخ / <strong>${name}</strong> نهائياً من قاعدة البيانات وحذف حسابه وفك ارتباط كافة حلقاته ومهامه؟`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'نعم، حذف نهائي',
            cancelButtonText: 'تراجع',
            confirmButtonColor: '#d33'
        });
        confirmed = result.isConfirmed;
    } else {
        confirmed = confirm(`هل أنت متأكد من حذف الشيخ (${name}) نهائياً من النظام وحذف حسابه وفك ارتباط حلقاته؟`);
    }

    if (confirmed) {
        try {
            const res = await apiRequest(`/teachers/${id}/permanent`, 'DELETE');
            showAlert(res?.message || res?.Message || "تم حذف المعلم نهائياً بنجاح.", "success");
            cachedTeachers = (cachedTeachers || []).filter(t => t.id != id);
            await loadAdminTeachers();
            if (typeof loadAdminCircles === "function") loadAdminCircles();
        } catch(err) {
            showAlert(err?.message || "حدث خطأ أثناء حذف المعلم لوجود ارتباطات في النظام", "danger");
        }
    }
}

async function manageTeacherRoles(teacherId) {
    let teacher = (cachedTeachers || []).find(t => t.id == teacherId);
    if (!teacher) {
        try {
            teacher = await apiRequest(`/teachers/${teacherId}`);
        } catch(e) {
            showAlert("تعذر العثور على بيانات المعلم", "danger");
            return;
        }
    }

    const currentTask = (teacher.taskRole || "").trim();

    const rolesList = [
        { id: "role-circle", name: "شيخ ومحفّظ حلقة قرآنية", val: "معلم حلقة", icon: "fa-mosque", color: "text-success", desc: "رصد الحضور اليومي، التسميع، والقرعة وإدارة طلاب حلقاتي" },
        { id: "role-preacher", name: "مشرف الفتى الواعظ والأصوات الندية", val: "الفتى الواعظ + الأصوات الندية", icon: "fa-microphone", color: "text-danger", desc: "سجل فرسان الخطابة، المواعظ الدعوية، والأذان والتلاوة" },
        { id: "role-exam", name: "مشرف ومقوّم اختبارات", val: "مشرف اختبارات", icon: "fa-clipboard-check", color: "text-warning", desc: "تقييم واختبار الطلاب في فروع وأجزاء القرآن الكريم" },
        { id: "role-mem", name: "مشرف شؤون التحفيظ ومنتدى الحفاظ", val: "التحفيظ + ملف منتدى الحفاظ", icon: "fa-book-quran", color: "text-primary", desc: "متابعة الخاتمين، أجزاء الحفظ المتقدمة، وترشيحات الاختبارات" },
        { id: "role-qual", name: "مسؤول الجودة والرقابة", val: "الجودة", icon: "fa-magnifying-glass-chart", color: "text-info", desc: "متابعة مؤشرات الأداء والتقييم الإشرافي للحلقات" },
        { id: "role-fin", name: "المسؤول المالي والمحافظ", val: "الملف المالي", icon: "fa-wallet", color: "text-success", desc: "إدارة كشوفات المحافظ البنكية، المكافآت، وتصدير إكسل مالي" },
        { id: "role-courses", name: "معلم الدورات العلمية والتجويد", val: "معلم دورات", icon: "fa-award", color: "text-secondary", desc: "إدارة دورات التجويد، رصد العلامات وإصدار الشهادات" },
        { id: "role-assistant", name: "مساعد حلقة قرآنية", val: "مساعد حلقة", icon: "fa-handshake-angle", color: "text-info", desc: "مشاركة نفس الحلقة مع المحفظ بنفس الصلاحيات التامة" },
        { id: "role-emir", name: "أمير المركز (الإدارة العامة)", val: "مركز البيان", icon: "fa-crown", color: "text-warning", desc: "صلاحيات الإدارة الكاملة للتقارير والإعدادات والمنظومة" }
    ];

    const rolesCardsHtml = rolesList.map(r => {
        const isChecked = currentTask.includes(r.val) || (r.val === "مركز البيان" && currentTask.includes("البيان"));
        return `
            <div class="col-md-6 mb-2">
                <div class="role-card-item border rounded-3 p-3 h-100 ${isChecked ? 'role-card-active' : ''}" data-val="${r.val}" style="cursor: pointer; transition: all 0.2s ease; background: ${isChecked ? '#f0fdf4' : '#ffffff'}; border-color: ${isChecked ? '#22c55e' : '#e2e8f0'} !important;">
                    <div class="d-flex align-items-start gap-3">
                        <div class="form-check mt-1">
                            <input class="form-check-input role-checkbox" type="checkbox" value="${r.val}" ${isChecked ? 'checked' : ''} style="cursor: pointer; transform: scale(1.2);">
                        </div>
                        <div class="flex-grow-1">
                            <div class="fw-bold d-flex align-items-center gap-2 mb-1" style="font-size: 0.95rem;">
                                <i class="fa-solid ${r.icon} ${r.color}"></i>
                                <span>${r.name}</span>
                            </div>
                            <small class="text-muted d-block" style="font-size: 0.8rem; line-height: 1.4;">${r.desc}</small>
                        </div>
                    </div>
                </div>
            </div>
        `;
    }).join("");

    const htmlContent = `
        <div class="text-start" style="direction: rtl;">
            <!-- Teacher Header Info -->
            <div class="p-3 bg-light border rounded-3 mb-3 d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1 fw-bold text-primary"><i class="fa-solid fa-user-tie me-1"></i> فضيلة الشيخ / ${teacher.fullName}</h5>
                    <div class="small text-muted font-monospace"><i class="fa-solid fa-id-card me-1"></i> رقم الهوية: <strong>${teacher.identityNumber || '-'}</strong> | الجوال: <strong>${teacher.contact || '-'}</strong></div>
                </div>
                <span class="badge bg-success bg-opacity-10 text-success fw-bold px-3 py-2 border border-success rounded-pill">تعديل الصلاحيات الفوري</span>
            </div>

            <div class="mb-2">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <label class="form-label fw-bold text-dark mb-0"><i class="fa-solid fa-shield-halved text-primary me-1"></i> حدد المهام والصلاحيات الموكلة للشيخ (يمكن اختيار أكثر من مهمة أو إبقاؤه غير مكلف):</label>
                    <button type="button" class="btn btn-outline-danger btn-sm py-0 px-2" id="btn-clear-all-roles" style="font-size: 0.8rem;"><i class="fa-solid fa-ban me-1"></i> تفريغ كافة المهام (غير مكلف)</button>
                </div>
                <div class="row g-2" id="roles-cards-grid">
                    ${rolesCardsHtml}
                </div>
            </div>

            <div class="mt-3 p-2 bg-light border rounded-3">
                <label class="form-label fw-bold small text-muted mb-1"><i class="fa-solid fa-file-signature text-secondary me-1"></i> نص التكليف المجمع النهائي:</label>
                <input id="swal-roles-summary-input" class="form-control form-control-sm fw-bold font-monospace text-primary" value="${currentTask || 'غير مكلف'}" placeholder="غير مكلف / بدون مهام">
                <small class="text-muted d-block mt-1"><i class="fa-solid fa-info-circle text-primary me-1"></i> إذا تركت الحقل غير مكلف أو بدون مهام، فلن تظهر للشيخ أي حلقات أو صلاحيات إدارية عند دخوله.</small>
            </div>
        </div>
    `;

    const result = await Swal.fire({
        title: `🛡️ إدارة صلاحيات ومهام الشيخ / ${teacher.fullName}`,
        html: htmlContent,
        showCancelButton: true,
        confirmButtonText: '<i class="fa-solid fa-floppy-disk me-1"></i> حفظ وتطبيق الصلاحيات فوراً',
        cancelButtonText: 'إلغاء',
        confirmButtonColor: '#0d5c3a',
        width: '780px',
        focusConfirm: false,
        didOpen: () => {
            const summaryInput = document.getElementById("swal-roles-summary-input");
            const updateSummary = () => {
                const checkedVals = [];
                document.querySelectorAll(".role-checkbox:checked").forEach(cb => {
                    if (cb.value) checkedVals.push(cb.value);
                });
                summaryInput.value = checkedVals.length > 0 ? checkedVals.join(" + ") : "غير مكلف";
            };

            const clearBtn = document.getElementById("btn-clear-all-roles");
            if (clearBtn) {
                clearBtn.addEventListener("click", () => {
                    document.querySelectorAll(".role-checkbox").forEach(cb => cb.checked = false);
                    document.querySelectorAll(".role-card-item").forEach(card => {
                        card.style.background = '#ffffff';
                        card.style.borderColor = '#e2e8f0';
                    });
                    summaryInput.value = "غير مكلف";
                });
            }

            document.querySelectorAll(".role-card-item").forEach(card => {
                card.addEventListener("click", (e) => {
                    if (e.target.tagName !== 'INPUT') {
                        const cb = card.querySelector(".role-checkbox");
                        cb.checked = !cb.checked;
                    }
                    const cb = card.querySelector(".role-checkbox");
                    if (cb.checked) {
                        card.style.background = '#f0fdf4';
                        card.style.borderColor = '#22c55e';
                    } else {
                        card.style.background = '#ffffff';
                        card.style.borderColor = '#e2e8f0';
                    }
                    updateSummary();
                });
            });
        },
        preConfirm: () => {
            const val = document.getElementById("swal-roles-summary-input").value.trim();
            return val || "غير مكلف";
        }
    });

    if (result.isConfirmed) {
        try {
            const updatedTaskRole = (typeof result.value === 'string' ? result.value : "").trim();
            const payload = {
                fullName: teacher.fullName,
                identityNumber: teacher.identityNumber,
                contact: teacher.contact,
                whatsappNumber: teacher.whatsappNumber,
                qualification: teacher.qualification,
                mosqueName: teacher.mosqueName,
                socialStatus: teacher.socialStatus,
                familyMembersCount: teacher.familyMembersCount,
                walletNumber: teacher.walletNumber,
                walletOwner: teacher.walletOwner,
                memorizedAjzaa: teacher.memorizedAjzaa,
                studentsCountTarget: teacher.studentsCountTarget,
                taskRole: updatedTaskRole,
                isActive: teacher.isActive
            };

            await apiRequest(`/teachers/${teacher.id}`, 'PUT', payload);
            showAlert(`تم تحديث وحفظ مهام وصلاحيات الشيخ (${teacher.fullName}) بنجاح! 🎉`, "success");
            await loadAdminTeachers();
        } catch(err) {
            showAlert(err.message || "حدث خطأ أثناء حفظ الصلاحيات", "danger");
        }
    }
}

async function showTeacherModal(teacherId = null) {
    let teacher = null;
    if (teacherId) {
        teacher = (cachedTeachers || []).find(t => t.id == teacherId);
        if (!teacher) {
            try {
                teacher = await apiRequest(`/teachers/${teacherId}`);
            } catch(e) {}
        }
    }

    const t = teacher || {
        fullName: "",
        identityNumber: "",
        contact: "",
        whatsappNumber: "",
        mosqueName: "علي بن أبي طالب",
        qualification: "",
        socialStatus: "أعزب",
        familyMembersCount: "",
        walletNumber: "",
        walletOwner: "",
        memorizedAjzaa: "",
        studentsCountTarget: "",
        taskRole: "غير مكلف",
        isActive: true
    };

    const currentTask = (t.taskRole && t.taskRole.trim()) ? t.taskRole : "غير مكلف";

    const availableRoles = [
        { key: "غير مكلف", label: "غير مكلف (بدون مهام)", icon: "fa-user-clock", colorClass: "chip-neutral", fullVal: "غير مكلف" },
        { key: "معلم حلقة", label: "معلم حلقة قرآنية", icon: "fa-mosque", colorClass: "chip-emerald", fullVal: "معلم حلقة" },
        { key: "مساعد حلقة", label: "مساعد حلقة", icon: "fa-handshake-angle", colorClass: "chip-teal", fullVal: "مساعد حلقة" },
        { key: "مشرف اختبارات", label: "مشرف ومقوّم اختبارات", icon: "fa-clipboard-check", colorClass: "chip-amber", fullVal: "مشرف اختبارات" },
        { key: "شؤون التحفيظ", label: "شؤون التحفيظ والحفاظ", icon: "fa-book-quran", colorClass: "chip-blue", fullVal: "التحفيظ + ملف منتدى الحفاظ" },
        { key: "الجودة والرقابة", label: "مسؤول الجودة والرقابة", icon: "fa-magnifying-glass-chart", colorClass: "chip-indigo", fullVal: "الجودة" },
        { key: "الملف المالي", label: "المسؤول المالي والمحافظ", icon: "fa-wallet", colorClass: "chip-green", fullVal: "الملف المالي" },
        { key: "معلم دورات", label: "معلم دورات علمية", icon: "fa-award", colorClass: "chip-purple", fullVal: "معلم دورات" },
        { key: "الفتى الواعظ", label: "مشرف الفتى الواعظ", icon: "fa-microphone", colorClass: "chip-rose", fullVal: "الفتى الواعظ + الأصوات الندية" },
        { key: "أمير المركز", label: "أمير المركز (الإدارة العامة)", icon: "fa-crown", colorClass: "chip-gold", fullVal: "مركز البيان" }
    ];

    const htmlContent = `
        <div class="teacher-modal-container">
            <!-- Header Banner -->
            <div class="teacher-modal-hero">
                <div class="d-flex align-items-center gap-3">
                    <div class="teacher-avatar-badge">
                        <i class="fa-solid fa-chalkboard-user"></i>
                    </div>
                    <div>
                        <h5 class="teacher-modal-heading">${teacherId ? `تعديل بيانات الشيخ / ${escapeXml(t.fullName)}` : 'تسجيل وإضافة معلم جديد بالكادر'}</h5>
                        <p class="teacher-modal-subheading">إدارة الملف الإداري والتكليفات والصلاحيات لمنظومة مركز البيان</p>
                    </div>
                </div>
                ${t.identityNumber ? `<span class="badge bg-white text-dark border px-3 py-2 rounded-pill font-monospace"><i class="fa-solid fa-id-card text-success me-1"></i> ${escapeXml(t.identityNumber)}</span>` : ''}
            </div>

            <!-- Section 1: البيانات الشخصية والتعريفية -->
            <div class="teacher-card-section">
                <div class="section-title-badge text-primary">
                    <i class="fa-solid fa-id-card"></i>
                    <span>1. البيانات الشخصية والتعريفية</span>
                </div>
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label-custom">الاسم الكامل (الرباعي) <span class="text-danger">*</span></label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-user input-icon text-primary"></i>
                            <input id="swal-tch-name" class="form-control-custom" placeholder="الاسم الرباعي الكامل للشيخ" value="${escapeXml(t.fullName || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">رقم الهوية الوطنية (اسم المستخدم للدخول) <span class="text-danger">*</span></label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-id-card input-icon text-primary"></i>
                            <input id="swal-tch-id" class="form-control-custom font-monospace" placeholder="رقم الهوية (9 أرقام)" value="${escapeXml(t.identityNumber || '')}" maxlength="9">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">المؤهل العلمي والتخصص</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-graduation-cap input-icon text-info"></i>
                            <input id="swal-tch-qual" class="form-control-custom" placeholder="مثال: بكالوريوس شريعة إسلامية / دبلوم" value="${escapeXml(t.qualification || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">المسجد التابع له</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-mosque input-icon text-success"></i>
                            <input id="swal-tch-mosque" class="form-control-custom" placeholder="مسجد علي بن أبي طالب" value="${escapeXml(t.mosqueName || 'علي بن أبي طالب')}">
                        </div>
                    </div>
                </div>
            </div>

            <!-- Section 2: الاتصال والتواصل الاجتماعي -->
            <div class="teacher-card-section">
                <div class="section-title-badge text-success">
                    <i class="fa-solid fa-phone-volume"></i>
                    <span>2. أرقام الاتصال والتواصل والبيانات الاجتماعية</span>
                </div>
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label-custom">رقم الجوال (اتصال)</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-phone input-icon text-success"></i>
                            <input id="swal-tch-phone" class="form-control-custom font-monospace" placeholder="059xxxxxxx" value="${escapeXml(t.contact || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">رقم الواتساب</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-brands fa-whatsapp input-icon text-success"></i>
                            <input id="swal-tch-whatsapp" class="form-control-custom font-monospace" placeholder="0097259xxxxxxx" value="${escapeXml(t.whatsappNumber || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">الحالة الاجتماعية</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-ring input-icon text-warning"></i>
                            <select id="swal-tch-social" class="form-control-custom">
                                <option value="أعزب" ${t.socialStatus === 'أعزب' ? 'selected' : ''}>أعزب</option>
                                <option value="متزوج" ${t.socialStatus === 'متزوج' ? 'selected' : ''}>متزوج</option>
                            </select>
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">عدد أفراد الأسرة</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-users input-icon text-primary"></i>
                            <input id="swal-tch-family" type="number" min="0" class="form-control-custom" placeholder="عدد الأفراد" value="${t.familyMembersCount || ''}">
                        </div>
                    </div>
                </div>
            </div>

            <!-- Section 3: الحفظ والمستهدف والبيانات المالية -->
            <div class="teacher-card-section">
                <div class="section-title-badge text-warning">
                    <i class="fa-solid fa-book-quran"></i>
                    <span>3. الحفظ والهدف القرآني والبيانات المالية</span>
                </div>
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label-custom">مقدار الحفظ من القرآن</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-book-open input-icon text-success"></i>
                            <input id="swal-tch-memorized" class="form-control-custom" placeholder="مثال: القرآن كاملاً / 20 جزء" value="${escapeXml(t.memorizedAjzaa || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">العدد المستهدف للطلاب بالحلقة</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-bullseye input-icon text-danger"></i>
                            <input id="swal-tch-target" class="form-control-custom" placeholder="مثال: 15 / 20 طالب" value="${escapeXml(t.studentsCountTarget || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">رقم المحفظة / الحساب البنكي</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-wallet input-icon text-warning"></i>
                            <input id="swal-tch-wallet" class="form-control-custom font-monospace" placeholder="رقم المحفظة الإلكترونية أو الحساب" value="${escapeXml(t.walletNumber || '')}">
                        </div>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label-custom">اسم صاحب المحفظة / الحساب</label>
                        <div class="input-icon-wrapper">
                            <i class="fa-solid fa-user-check input-icon text-dark"></i>
                            <input id="swal-tch-wallet-owner" class="form-control-custom" placeholder="اسم صاحب الحساب أو المحفظة" value="${escapeXml(t.walletOwner || '')}">
                        </div>
                    </div>
                </div>
            </div>

            <!-- Section 4: DYNAMIC ROLE & TASK SELECTOR (الأزرار التفاعلية الذكية) -->
            <div class="teacher-card-section teacher-roles-card">
                <div class="d-flex justify-content-between align-items-center mb-2 flex-wrap gap-2">
                    <div class="section-title-badge text-dark mb-0">
                        <i class="fa-solid fa-shield-halved text-success"></i>
                        <span>4. الوظيفة والتكليف المخصص (الصلاحيات والصفحات)</span>
                    </div>
                    <span class="badge-pill-notice">
                        <i class="fa-solid fa-wand-magic-sparkles me-1 text-warning"></i> تحديد تفاعلي فوري
                    </span>
                </div>

                <p class="role-instructions-text">
                    اضغط على أي زر لإضافته لتكليف الشيخ أو إلغائه، أو اختر <strong>(غير مكلف)</strong> لمن ليس لديه تكليف حالياً:
                </p>

                <!-- Chips Grid -->
                <div class="role-chips-grid" id="role-chips-container">
                    <!-- Dynamic role chip buttons rendered here -->
                </div>

                <!-- Role Summary & Manual Edit -->
                <div class="role-summary-box">
                    <div class="d-flex justify-content-between align-items-center mb-2 flex-wrap gap-2">
                        <label class="form-label-custom fw-bold mb-0">
                            <i class="fa-solid fa-file-signature text-primary me-1"></i> ملخص المهام الموكلة (يتم تحديثه تلقائياً):
                        </label>
                        <button type="button" class="btn-clear-roles-custom" id="btn-reset-to-unassigned">
                            <i class="fa-solid fa-ban me-1"></i> تعيين كـ "غير مكلف"
                        </button>
                    </div>
                    <input id="swal-tch-task" class="form-control-custom form-control-task font-monospace" placeholder="مثال: معلم حلقة + مشرف اختبارات" value="${escapeXml(currentTask)}">
                    <div class="d-flex align-items-center gap-2 mt-2 text-muted small">
                        <i class="fa-solid fa-circle-info text-success"></i>
                        <span>تحدد هذه المهام الصفحات والأدوات التي تظهر للشيخ تلقائياً عند تسجيل دخوله للمنظومة.</span>
                    </div>
                </div>
            </div>
        </div>
    `;

    const result = await Swal.fire({
        title: teacherId ? `✏️ تعديل بيانات الشيخ / ${escapeXml(t.fullName)}` : '➕ إضافة معلم جديد للكادر',
        html: htmlContent,
        showCancelButton: true,
        confirmButtonText: '<i class="fa-solid fa-floppy-disk me-1"></i> حفظ وتثبيت التعديلات',
        cancelButtonText: 'إلغاء',
        confirmButtonColor: '#0d5c3a',
        width: '840px',
        focusConfirm: false,
        didOpen: () => {
            const taskInput = document.getElementById("swal-tch-task");
            const container = document.getElementById("role-chips-container");
            const resetBtn = document.getElementById("btn-reset-to-unassigned");

            function parseCurrentKeys(text) {
                if (!text || text.trim() === "" || text.includes("غير مكلف") || text.includes("بدون تكليف")) {
                    return ["غير مكلف"];
                }
                const matched = [];
                for (let r of availableRoles) {
                    if (r.key === "غير مكلف") continue;
                    if (text.includes(r.key) || text.includes(r.fullVal) || (r.key === "مركز البيان" && (text.includes("البيان") || text.includes("أمير المركز")))) {
                        matched.push(r.key);
                    }
                }
                return matched.length > 0 ? matched : ["غير مكلف"];
            }

            let selectedKeys = parseCurrentKeys(taskInput.value);

            function renderChips() {
                container.innerHTML = availableRoles.map(r => {
                    const isActive = selectedKeys.includes(r.key);
                    return `
                        <button type="button" class="role-chip-btn ${r.colorClass} ${isActive ? 'active' : ''}" data-key="${r.key}">
                            <i class="fa-solid ${r.icon} chip-icon"></i>
                            <span>${r.label}</span>
                            <i class="fa-solid fa-circle-check chip-check ms-1"></i>
                        </button>
                    `;
                }).join("");

                container.querySelectorAll(".role-chip-btn").forEach(btn => {
                    btn.addEventListener("click", () => {
                        const key = btn.dataset.key;
                        toggleRoleKey(key);
                    });
                });
            }

            function toggleRoleKey(key) {
                if (key === "غير مكلف") {
                    selectedKeys = ["غير مكلف"];
                } else {
                    selectedKeys = selectedKeys.filter(k => k !== "غير مكلف");
                    if (selectedKeys.includes(key)) {
                        selectedKeys = selectedKeys.filter(k => k !== key);
                    } else {
                        selectedKeys.push(key);
                    }
                    if (selectedKeys.length === 0) {
                        selectedKeys = ["غير مكلف"];
                    }
                }
                renderChips();
                syncTaskInputFromKeys();
            }

            function syncTaskInputFromKeys() {
                if (selectedKeys.length === 0 || (selectedKeys.length === 1 && selectedKeys[0] === "غير مكلف")) {
                    taskInput.value = "غير مكلف";
                } else {
                    const vals = selectedKeys
                        .map(k => availableRoles.find(r => r.key === k)?.fullVal || k)
                        .filter(v => v && v !== "غير مكلف");
                    taskInput.value = vals.join(" + ");
                }
            }

            taskInput.addEventListener("input", () => {
                selectedKeys = parseCurrentKeys(taskInput.value);
                renderChips();
            });

            if (resetBtn) {
                resetBtn.addEventListener("click", () => {
                    selectedKeys = ["غير مكلف"];
                    taskInput.value = "غير مكلف";
                    renderChips();
                });
            }

            renderChips();
        },
        preConfirm: () => {
            const fullName = document.getElementById("swal-tch-name").value.trim();
            const identityNumber = document.getElementById("swal-tch-id").value.trim();
            const contact = document.getElementById("swal-tch-phone").value.trim();
            const whatsappNumber = document.getElementById("swal-tch-whatsapp").value.trim();
            const qualification = document.getElementById("swal-tch-qual").value.trim();
            const mosqueName = document.getElementById("swal-tch-mosque").value.trim();
            const socialStatus = document.getElementById("swal-tch-social").value;
            const familyMembersCount = document.getElementById("swal-tch-family").value.trim();
            const walletNumber = document.getElementById("swal-tch-wallet").value.trim();
            const walletOwner = document.getElementById("swal-tch-wallet-owner").value.trim();
            const memorizedAjzaa = document.getElementById("swal-tch-memorized").value.trim();
            const studentsCountTarget = document.getElementById("swal-tch-target").value.trim();
            const taskRole = document.getElementById("swal-tch-task").value.trim();

            if (!fullName) {
                Swal.showValidationMessage("يرجى إدخال الاسم الرباعي للمعلم.");
                return false;
            }
            if (!identityNumber) {
                Swal.showValidationMessage("يرجى إدخال رقم الهوية الوطنية (يُستخدم كاسم مستخدم للدخول).");
                return false;
            }

            return {
                fullName,
                identityNumber,
                contact,
                whatsappNumber,
                qualification,
                mosqueName,
                socialStatus,
                familyMembersCount: familyMembersCount ? parseInt(familyMembersCount) : null,
                walletNumber,
                walletOwner,
                memorizedAjzaa,
                studentsCountTarget,
                taskRole,
                isActive: t.isActive
            };
        }
    });

    if (result.isConfirmed && result.value) {
        try {
            if (teacherId) {
                await apiRequest(`/teachers/${teacherId}`, 'PUT', result.value);
                showAlert("تم حفظ وتحديث بيانات الشيخ ومهامه الإدارية بنجاح دائم! 🎉", "success");
            } else {
                await apiRequest('/teachers', 'POST', result.value);
                showAlert("تمت إضافة المعلم الجديد وتعيين حسابه بنجاح! 🌟", "success");
            }
            await loadAdminTeachers();
        } catch(err) {
            showAlert(err.message || "حدث خطأ أثناء حفظ بيانات المعلم", "danger");
        }
    }
}

function getOrphanBadgeHtml(fatherStatus, motherStatus) {
    const f = (fatherStatus || '').trim();
    const m = (motherStatus || '').trim();

    const fOrphan = (f === 'شهيد' || f === 'متوفي' || f === 'شهيدة' || f === 'متوفاة');
    const mOrphan = (m === 'شهيد' || m === 'متوفي' || m === 'شهيدة' || m === 'متوفاة');

    if (fOrphan && mOrphan) {
        return `<span class="badge bg-danger text-white ms-1 px-2 py-1 shadow-sm" style="font-size:0.78rem;"><i class="fa-solid fa-ribbon me-1"></i> يتيم الأبوين (شهيدين/متوفين)</span>`;
    } else if (fOrphan) {
        return `<span class="badge bg-danger text-white ms-1 px-2 py-1 shadow-sm" style="font-size:0.78rem;"><i class="fa-solid fa-ribbon me-1"></i> يتيم الأب (${f})</span>`;
    } else if (mOrphan) {
        return `<span class="badge bg-danger text-white ms-1 px-2 py-1 shadow-sm" style="font-size:0.78rem;"><i class="fa-solid fa-ribbon me-1"></i> يتيم الأم (${m})</span>`;
    } else if (f && f !== 'سليم' && f !== 'حي') {
        return `<span class="badge bg-warning text-dark ms-1 px-2 py-1 shadow-sm" style="font-size:0.78rem;"><i class="fa-solid fa-notes-medical me-1"></i> حالة الأب: ${f}</span>`;
    }
    return '';
}

// ----------------- Admin: Students Management -----------------
async function loadAdminStudents(search = "") {
    const tbody = document.getElementById("students-table-body");
    if (tbody && (!cachedStudents || cachedStudents.length === 0)) {
        tbody.innerHTML = `<tr><td colspan="8" class="text-center py-4 text-muted"><i class="fa-solid fa-spinner fa-spin fa-2x text-primary"></i><p class="mt-2 mb-0">جاري تحميل بيانات الطلاب من الخادم...</p></td></tr>`;
    }
    
    try {
        const students = await apiRequest(`/students?search=${search}`);
        cachedStudents = students;
        
        if (tbody) tbody.innerHTML = "";
        
        if (students.length === 0) {
            tbody.innerHTML = `<tr><td colspan="8" class="text-center text-muted py-4">لا يوجد طلاب يطابقون البحث.</td></tr>`;
            return;
        }
        
        students.forEach((s, idx) => {
            const tr = document.createElement("tr");
            tr.innerHTML = `
                <td class="fw-bold text-muted">${idx + 1}</td>
                <td style="white-space: nowrap; min-width: 200px;">
                    <strong class="clickable-student-360 d-inline-block me-1" data-id="${s.id}" style="color: var(--primary-color); cursor: pointer; text-decoration: underline;">${s.fullName}</strong>
                    ${getOrphanBadgeHtml(s.fatherStatus, s.motherStatus)}
                </td>
                <td style="white-space: nowrap;" class="font-monospace">${s.familyContact}</td>
                <td style="white-space: nowrap;" class="font-monospace">${s.dateOfBirth}</td>
                <td style="white-space: nowrap;">${s.circleName || '<span class="text-muted">غير منسب حلقة</span>'}</td>
                <td style="white-space: nowrap;"><code class="px-2 py-0.5 bg-light rounded border">${s.parentId || 'غير مسجل'}</code></td>
                <td style="white-space: nowrap;">
                    <span class="badge ${s.isActive ? 'badge-success' : 'badge-danger'}">
                        ${s.isActive ? 'نشط' : 'معطّل'}
                    </span>
                </td>
                <td style="white-space: nowrap;" class="text-center">
                    <div class="d-inline-flex gap-1">
                        <button class="btn btn-outline-primary btn-sm py-1 px-2.5 btn-edit-student" data-id="${s.id}" title="تعديل البيانات"><i class="fa-solid fa-pen"></i> تعديل</button>
                        <button class="btn ${s.isActive ? 'btn-warning text-dark' : 'btn-success'} btn-sm py-1 px-2.5 btn-toggle-student" data-id="${s.id}" title="${s.isActive ? 'تعطيل مؤقت' : 'تنشيط'}">
                            <i class="fa-solid ${s.isActive ? 'fa-ban' : 'fa-check'}"></i> ${s.isActive ? 'تعطيل' : 'تنشيط'}
                        </button>
                        <button class="btn btn-danger btn-sm py-1 px-2.5 btn-hard-delete-student" data-id="${s.id}" data-name="${s.fullName}" title="حذف نهائي شامل">
                            <i class="fa-solid fa-trash-can"></i> حذف نهائي
                        </button>
                    </div>
                </td>
            `;
            tbody.appendChild(tr);
        });
        
        // Bind Actions
        tbody.querySelectorAll(".clickable-student-360").forEach(el => {
            el.addEventListener("click", (e) => {
                const studentId = e.target.dataset.id;
                showStudent360View(studentId);
            });
        });
        tbody.querySelectorAll(".btn-edit-student").forEach(btn => {
            btn.addEventListener("click", (e) => showStudentModal(e.target.closest("button").dataset.id));
        });
        tbody.querySelectorAll(".btn-toggle-student").forEach(btn => {
            btn.addEventListener("click", (e) => toggleStudentActive(e.target.closest("button").dataset.id));
        });
        tbody.querySelectorAll(".btn-hard-delete-student").forEach(btn => {
            btn.addEventListener("click", (e) => {
                const b = e.target.closest("button");
                hardDeleteStudent(b.dataset.id, b.dataset.name);
            });
        });
        
    } catch(e) {
        console.error(e);
        if (tbody) {
            tbody.innerHTML = `
                <tr>
                    <td colspan="8" class="text-center py-4">
                        <div class="text-danger mb-2"><i class="fa-solid fa-circle-exclamation fa-2x"></i></div>
                        <p class="text-danger fw-bold mb-2">تعذر جلب بيانات الطلاب (قد يكون الخادم السحابي في طور الاستيقاظ).</p>
                        <button class="btn btn-sm btn-primary shadow-sm" onclick="loadAdminStudents()"><i class="fa-solid fa-rotate-right me-1"></i> إعادة المحاولة الآن</button>
                    </td>
                </tr>
            `;
        }
    }
}

// ----------------- Teacher: Attendance Setup -----------------
async function loadTeacherAttendanceSetup() {
    try {
        const circles = await apiRequest("/circles");
        
        // Backend API already filters circles for current teacher
        const myCircles = circles.filter(c => c.isActive);
        
        const select = document.getElementById("attendance-circle-select");
        select.innerHTML = "";
        
        if (myCircles.length === 0) {
            select.innerHTML = `<option value="">لا يوجد حلقات مسندة إليك</option>`;
            document.getElementById("attendance-list-card").classList.add("hidden");
            return;
        }
        
        myCircles.forEach(c => {
            const opt = document.createElement("option");
            opt.value = c.id;
            opt.textContent = c.name;
            select.appendChild(opt);
        });
        
        // Hide list card until user loads it
        document.getElementById("attendance-list-card").classList.add("hidden");
        
    } catch(e) {
        console.error(e);
    }
}

// ----------------- Teacher: Students & Enrollment Management -----------------
async function loadTeacherStudentsSetup() {
    try {
        const circles = await apiRequest("/circles");
        const myCircles = (circles || []).filter(c => c.isActive);
        const select = document.getElementById("teacher-students-circle-select");
        if (!select) return;
        select.innerHTML = "";

        if (myCircles.length === 0) {
            select.innerHTML = `<option value="">لا توجد حلقات مسندة إليك</option>`;
            const tbody = document.getElementById("teacher-students-table-body");
            if (tbody) tbody.innerHTML = `<tr><td colspan="7" class="text-center text-muted p-4">لا توجد حلقات مسندة إلى حسابك حالياً.</td></tr>`;
            return;
        }

        myCircles.forEach(c => {
            const opt = document.createElement("option");
            opt.value = c.id;
            opt.textContent = c.name;
            select.appendChild(opt);
        });

        // Check if teacher enrollment is permitted
        const enrollBtnExisting = document.getElementById("btn-teacher-enroll-existing");
        const enrollBtnNew = document.getElementById("btn-teacher-add-new-student");
        if (window.SYS_ALLOW_TEACHER_ENROLL === false) {
            if (enrollBtnExisting) enrollBtnExisting.style.display = "none";
            if (enrollBtnNew) enrollBtnNew.style.display = "none";
        } else {
            if (enrollBtnExisting) enrollBtnExisting.style.display = "inline-flex";
            if (enrollBtnNew) enrollBtnNew.style.display = "inline-flex";
        }

        await loadTeacherStudentsTable();
    } catch (e) {
        console.error("Error loading teacher students setup:", e);
    }
}

async function loadTeacherStudentsTable() {
    const select = document.getElementById("teacher-students-circle-select");
    if (!select || !select.value) return;
    const circleId = select.value;

    const tbody = document.getElementById("teacher-students-table-body");
    if (tbody) tbody.innerHTML = `<tr><td colspan="7" class="text-center p-4"><i class="fa-solid fa-spinner fa-spin text-success fs-3"></i> جاري تحميل بيانات الطلاب...</td></tr>`;

    try {
        const circle = await apiRequest(`/circles/${circleId}`);
        const students = circle.students || [];

        const capBadge = document.getElementById("teacher-circle-capacity-badge");
        const maxCap = window.SYS_MAX_STUDENTS_CIRCLE || 25;
        if (capBadge) {
            capBadge.textContent = `سعة الحلقة: ${students.length} / ${maxCap} طالب`;
            if (students.length >= maxCap) {
                capBadge.className = "badge bg-danger fs-6 px-3 py-2 rounded-pill shadow-xs";
                capBadge.textContent += " (الحلقة ممتلئة)";
            } else {
                capBadge.className = "badge bg-success fs-6 px-3 py-2 rounded-pill shadow-xs";
            }
        }

        if (students.length === 0) {
            if (tbody) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="7" class="text-center p-4 text-muted">
                            <i class="fa-solid fa-users-slash fs-2 mb-2 d-block text-secondary"></i>
                            لا يوجد طلاب منتسبين في هذه الحلقة حالياً.<br>
                            ${window.SYS_ALLOW_TEACHER_ENROLL === true ? '<button class="btn btn-sm btn-primary mt-2 rounded-pill px-3" onclick="showTeacherEnrollExistingModal()"><i class="fa-solid fa-user-plus me-1"></i> تنسيب طالب موجود الآن</button>' : ''}
                        </td>
                    </tr>
                `;
            }
            return;
        }

        // Fetch full details of these students
        let fullStudents = [];
        try {
            const allMyStudents = await apiRequest("/students");
            fullStudents = allMyStudents || [];
        } catch(e) {}

        const hideParentPhone = window.SYS_HIDE_PARENT_PHONE === true;
        const allowEditPlan = window.SYS_ALLOW_TEACHER_EDIT_PLAN === true;
        const allowEnroll = window.SYS_ALLOW_TEACHER_ENROLL === true;

        let rowsHtml = "";
        students.forEach((s, idx) => {
            const fullS = fullStudents.find(x => x.id === s.id) || s;
            let displayPhone = fullS.familyContact || fullS.studentMobile || "-";
            if (hideParentPhone && displayPhone !== "-") {
                displayPhone = displayPhone.substring(0, 4) + "****" + displayPhone.slice(-2);
            }

            rowsHtml += `
                <tr>
                    <td><strong>${idx + 1}</strong></td>
                    <td>
                        <div class="fw-bold text-dark">${s.fullName}</div>
                        <small class="text-muted">${fullS.parentName ? 'ولي الأمر: ' + fullS.parentName : ''}</small>
                    </td>
                    <td><span class="badge bg-light text-dark border">${fullS.studentIdentityNumber || s.id}</span></td>
                    <td><span class="badge bg-success bg-opacity-10 text-success fw-bold">${fullS.previousQuranMemorization || 'مبتدئ'}</span></td>
                    <td><span class="text-muted"><i class="fa-solid fa-phone me-1"></i>${displayPhone}</span></td>
                    <td><small class="text-muted">${fullS.address || '-'}</small></td>
                    <td>
                        <div class="d-flex gap-1 flex-wrap">
                            <button class="btn btn-outline-info btn-sm rounded-pill px-2" onclick="showStudentProgressModal(${s.id})" title="عرض بطاقة الطالب الشاملة">
                                <i class="fa-solid fa-id-card"></i> بطاقة الطالب
                            </button>
                            ${allowEditPlan ? `
                            <button class="btn btn-outline-warning btn-sm rounded-pill px-2" onclick="showTeacherEditStudentPlanModal(${s.id}, '${s.fullName.replace(/'/g, "\\'")}', '${fullS.previousQuranMemorization || ''}')" title="تعديل خطة الحفظ">
                                <i class="fa-solid fa-pen-to-square"></i> الخطة
                            </button>` : ''}
                            ${allowEnroll ? `
                            <button class="btn btn-outline-danger btn-sm rounded-pill px-2" onclick="unenrollStudentFromCircle(${s.id}, '${s.fullName.replace(/'/g, "\\'")}', ${circleId})" title="إلغاء تنسيب الطالب من الحلقة">
                                <i class="fa-solid fa-user-minus"></i>
                            </button>` : ''}
                        </div>
                    </td>
                </tr>
            `;
        });
        if (tbody) tbody.innerHTML = rowsHtml;

    } catch (e) {
        console.error("Error rendering teacher students table:", e);
        if (tbody) tbody.innerHTML = `<tr><td colspan="7" class="text-center text-danger p-4">حدث خطأ أثناء تحميل بيانات الحلقة.</td></tr>`;
    }
}

// Modal for Teacher to enroll existing student in the center into their circle
async function showTeacherEnrollExistingModal() {
    if (window.SYS_ALLOW_TEACHER_ENROLL === false) {
        showAlert("تنسيب الطلاب بواسطة المعلم معطل حالياً من قبل إدارة المركز.", "warning");
        return;
    }

    try {
        const circles = await apiRequest("/circles");
        const myCircles = (circles || []).filter(c => c.isActive);
        if (myCircles.length === 0) {
            showAlert("لا توجد حلقات مسندة إليك لتنسيب الطلاب إليها.", "warning");
            return;
        }

        openModal("تنسيب طالب إلى حلقتي القرآنيّة");

        const modalBody = document.getElementById("modal-body-content");
        modalBody.innerHTML = `
            <div class="p-3" style="direction: rtl;">
                <div class="alert alert-info d-flex align-items-center justify-content-between gap-2 mb-3">
                    <div class="d-flex align-items-center gap-2">
                        <i class="fa-solid fa-circle-info fs-4 text-primary"></i>
                        <div>
                            <strong>تنسيب الطلاب للحلقة:</strong> يمكنك استعراض والبحث في كافة طلاب المركز القرآني وإضافتهم مباشرة إلى حلقتك.
                        </div>
                    </div>
                    <span id="teacher-enroll-badge-count" class="badge bg-primary bg-opacity-10 text-primary border border-primary px-3 py-2 rounded-pill fs-6 fw-bold">
                        <i class="fa-solid fa-spinner fa-spin me-1"></i> جاري التحميل...
                    </span>
                </div>

                <div class="row g-2 mb-3">
                    <div class="col-md-6">
                        <label class="form-label fw-bold text-dark"><i class="fa-solid fa-circle-nodes text-primary me-1"></i> اختر الحلقة المستهدفة للتنسيب:</label>
                        <select id="teacher-enroll-target-circle" class="form-select shadow-xs border-primary">
                            ${myCircles.map(c => `<option value="${c.id}">${c.name}</option>`).join('')}
                        </select>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label fw-bold text-dark"><i class="fa-solid fa-filter text-secondary me-1"></i> تصفية الطلاب:</label>
                        <div class="btn-group w-100 shadow-xs" role="group">
                            <input type="radio" class="btn-check" name="teacher-filter-status" id="filter-status-all" value="all" checked autocomplete="off">
                            <label class="btn btn-outline-primary btn-sm py-2 fw-bold" for="filter-status-all">جميع طلاب المركز</label>

                            <input type="radio" class="btn-check" name="teacher-filter-status" id="filter-status-unassigned" value="unassigned" autocomplete="off">
                            <label class="btn btn-outline-success btn-sm py-2 fw-bold" for="filter-status-unassigned">غير مسندين</label>

                            <input type="radio" class="btn-check" name="teacher-filter-status" id="filter-status-assigned" value="assigned" autocomplete="off">
                            <label class="btn btn-outline-warning text-dark btn-sm py-2 fw-bold" for="filter-status-assigned">مسندين بحلقات</label>
                        </div>
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold text-dark"><i class="fa-solid fa-magnifying-glass text-success me-1"></i> ابحث عن أي طالب بالاسم أو رقم الهوية أو الهاتف (بحث فوري وشامل):</label>
                    <div class="input-group">
                        <input type="text" id="teacher-enroll-search-input" class="form-control form-control-lg shadow-xs" placeholder="🔍 اكتب اسم الطالب أو رقم الهوية أو الهاتف للبحث في كافة طلاب المركز..." autocomplete="off">
                        <button class="btn btn-outline-secondary" type="button" id="btn-clear-teacher-search" title="مسح البحث"><i class="fa-solid fa-xmark"></i></button>
                    </div>
                </div>

                <div id="teacher-enroll-results-container" style="max-height: 380px; overflow-y: auto;" class="border rounded-3 p-2 bg-light">
                    <p class="text-center text-muted my-4"><i class="fa-solid fa-spinner fa-spin me-2"></i> جاري جلب كافة طلاب المركز...</p>
                </div>

                <!-- Footer with Dynamic Capacity and Cancel Button -->
                <div class="d-flex justify-content-between align-items-center mt-3 pt-3 border-top flex-wrap gap-2">
                    <div id="teacher-enroll-capacity-footer" class="small fw-bold"></div>
                    <button type="button" class="btn btn-secondary rounded-pill px-4 shadow-xs" onclick="closeModal()">
                        <i class="fa-solid fa-xmark me-1"></i> إلغاء / إغلاق النافذة
                    </button>
                </div>
            </div>
        `;

        // Fetch all students available in center
        let allStudents = [];
        try {
            allStudents = await apiRequest("/students/all-for-enrollment");
        } catch(e) {}
        
        if (!Array.isArray(allStudents) || allStudents.length === 0) {
            try {
                allStudents = await apiRequest("/students?all=true");
            } catch(e) {}
        }
        if (!Array.isArray(allStudents)) allStudents = [];

        const updateBadgeCount = () => {
            const badgeCount = document.getElementById("teacher-enroll-badge-count");
            if (badgeCount) {
                badgeCount.innerHTML = `<i class="fa-solid fa-users me-1"></i> ${allStudents.length} طالب بالمركز`;
            }
        };
        updateBadgeCount();

        let currentFilterStatus = "all";

        const updateCapacityFooter = () => {
            const circleSelect = document.getElementById("teacher-enroll-target-circle");
            const footer = document.getElementById("teacher-enroll-capacity-footer");
            if (!circleSelect || !footer) return;

            const targetCircleId = parseInt(circleSelect.value);
            const targetCircle = myCircles.find(c => c.id === targetCircleId);
            const currentCount = allStudents.filter(s => s.circleId === targetCircleId && s.isActive !== false).length;
            const maxCap = window.SYS_MAX_STUDENTS_CIRCLE || 20;
            const isFull = currentCount >= maxCap;

            footer.innerHTML = `
                <span class="badge ${isFull ? 'bg-danger' : 'bg-success'} fs-6 px-3 py-2 rounded-pill shadow-xs">
                    <i class="fa-solid ${isFull ? 'fa-triangle-exclamation' : 'fa-users'} me-1"></i>
                    سعة حلقة (${escapeXml(targetCircle ? targetCircle.name : 'الحلقة')}): ${currentCount} / ${maxCap} طالب ${isFull ? '(الحلقة ممتلئة)' : ''}
                </span>
            `;
            return { currentCount, maxCap, isFull };
        };

        const renderResults = () => {
            const container = document.getElementById("teacher-enroll-results-container");
            if (!container) return;

            const circleSelect = document.getElementById("teacher-enroll-target-circle");
            const targetCircleId = circleSelect ? parseInt(circleSelect.value) : 0;
            const capInfo = updateCapacityFooter() || { currentCount: 0, maxCap: 20, isFull: false };

            const searchInput = document.getElementById("teacher-enroll-search-input");
            const q = (searchInput ? searchInput.value : "").trim();

            const filtered = allStudents.filter(s => {
                const hasCircle = s.circleId && s.circleId > 0 && s.circleName && s.circleName !== "غير مسند حلقة";
                if (currentFilterStatus === "unassigned" && hasCircle) return false;
                if (currentFilterStatus === "assigned" && !hasCircle) return false;

                if (!q) return true;

                const nameMatch = matchArabicSearch(s.fullName, q);
                const idMatch = s.studentIdentityNumber && String(s.studentIdentityNumber).includes(q);
                const phoneMatch = (s.familyContact && String(s.familyContact).includes(q)) || (s.studentMobile && String(s.studentMobile).includes(q));
                const circleMatch = matchArabicSearch(s.circleName, q);

                return nameMatch || idMatch || phoneMatch || circleMatch;
            });

            if (filtered.length === 0) {
                container.innerHTML = `<div class="text-center text-muted my-4 p-3"><i class="fa-solid fa-users-slash fs-2 mb-2 d-block text-secondary"></i>لا يوجد طلاب مطابقين للبحث. يمكنك تجربة كتابة مقطع من الاسم أو رقم الهوية.</div>`;
                return;
            }

            let html = `<div class="small text-muted mb-2 px-2 d-flex justify-content-between align-items-center">
                <span>تم العثور على <strong>${filtered.length}</strong> طالب من إجمالي <strong>${allStudents.length}</strong> طالب</span>
            </div>`;

            html += '<div class="list-group list-group-flush gap-2">';
            filtered.forEach(s => {
                const hasCircle = s.circleId && s.circleId > 0 && s.circleName && s.circleName !== "غير مسند حلقة";
                const isAlreadyInThisCircle = (s.circleId === targetCircleId);
                const isInAnotherCircle = hasCircle && !isAlreadyInThisCircle;

                let actionButtonHtml = "";
                if (isAlreadyInThisCircle) {
                    actionButtonHtml = `
                        <button type="button" class="btn btn-outline-secondary btn-sm rounded-pill px-3 fw-bold flex-shrink-0" disabled>
                            <i class="fa-solid fa-check me-1"></i> مُنسّب بحلقتك
                        </button>
                    `;
                } else if (isInAnotherCircle) {
                    actionButtonHtml = `
                        <button type="button" class="btn btn-outline-warning text-dark btn-sm rounded-pill px-3 fw-bold flex-shrink-0" onclick="warnStudentInOtherCircle('${s.fullName.replace(/'/g, "\\'")}', '${(s.circleName || '').replace(/'/g, "\\'")}', '${(s.teacherName || '').replace(/'/g, "\\'")}')" title="الطالب منسب لحلقة أخرى">
                            <i class="fa-solid fa-lock me-1"></i> مُنسّب لحلقة أخرى
                        </button>
                    `;
                } else {
                    // Unassigned student
                    if (capInfo.isFull) {
                        actionButtonHtml = `
                            <button type="button" class="btn btn-outline-danger btn-sm rounded-pill px-3 fw-bold flex-shrink-0" disabled title="الحلقة ممتلئة بالكامل">
                                <i class="fa-solid fa-ban me-1"></i> الحلقة ممتلئة
                            </button>
                        `;
                    } else {
                        actionButtonHtml = `
                            <button type="button" class="btn btn-success btn-sm rounded-pill px-3 fw-bold shadow-xs flex-shrink-0 btn-enroll-action-${s.id}" onclick="executeTeacherStudentEnrollment(${s.id}, '${s.fullName.replace(/'/g, "\\'")}', this)">
                                <i class="fa-solid fa-plus me-1"></i> تنسيب لحلقتي
                            </button>
                        `;
                    }
                }

                html += `
                    <div class="list-group-item list-group-item-action d-flex justify-content-between align-items-center p-3 rounded-3 shadow-xs bg-white border">
                        <div>
                            <div class="fw-bold text-dark fs-6 d-flex align-items-center gap-2">
                                <i class="fa-solid fa-user-graduate text-success"></i>
                                <span>${escapeXml(s.fullName)}</span>
                            </div>
                            <div class="small text-muted mt-1 d-flex flex-wrap gap-2 align-items-center">
                                <span class="badge bg-light text-secondary border">هوية: ${escapeXml(s.studentIdentityNumber || s.id)}</span>
                                ${s.familyContact ? `<span class="badge bg-light text-muted border"><i class="fa-solid fa-phone me-1"></i>${escapeXml(s.familyContact)}</span>` : ''}
                                ${hasCircle ? `<span class="badge bg-warning bg-opacity-25 text-dark border"><i class="fa-solid fa-mosque me-1"></i>الحلقة: ${escapeXml(s.circleName)} ${s.teacherName ? `(الشيخ: ${escapeXml(s.teacherName)})` : ''}</span>` : '<span class="badge bg-success bg-opacity-25 text-success border"><i class="fa-solid fa-check me-1"></i>غير مسند حلقة</span>'}
                            </div>
                        </div>
                        ${actionButtonHtml}
                    </div>
                `;
            });
            html += '</div>';
            container.innerHTML = html;
        };

        renderResults();

        // When target circle changes, update capacity and re-render
        const targetCircleSelect = document.getElementById("teacher-enroll-target-circle");
        if (targetCircleSelect) {
            targetCircleSelect.addEventListener("change", () => {
                renderResults();
            });
        }

        let liveSearchTimer = null;
        const searchInput = document.getElementById("teacher-enroll-search-input");
        if (searchInput) {
            searchInput.addEventListener("input", () => {
                renderResults();

                // Live search to backend API in parallel to catch any students dynamically
                clearTimeout(liveSearchTimer);
                const queryVal = searchInput.value.trim();
                if (queryVal.length >= 2) {
                    liveSearchTimer = setTimeout(async () => {
                        try {
                            const results = await apiRequest(`/students/all-for-enrollment?search=${encodeURIComponent(queryVal)}`);
                            if (Array.isArray(results) && results.length > 0) {
                                let hasNew = false;
                                results.forEach(st => {
                                    if (!allStudents.some(item => item.id === st.id)) {
                                        allStudents.push(st);
                                        hasNew = true;
                                    }
                                });
                                if (hasNew) {
                                    updateBadgeCount();
                                    renderResults();
                                }
                            }
                        } catch(err) {}
                    }, 350);
                }
            });
        }

        const clearBtn = document.getElementById("btn-clear-teacher-search");
        if (clearBtn) {
            clearBtn.addEventListener("click", () => {
                if (searchInput) {
                    searchInput.value = "";
                    renderResults();
                }
            });
        }

        document.querySelectorAll("input[name='teacher-filter-status']").forEach(radio => {
            radio.addEventListener("change", (e) => {
                currentFilterStatus = e.target.value;
                renderResults();
            });
        });

    } catch (e) {
        console.error("Error in showTeacherEnrollExistingModal:", e);
        showAlert("تعذر فتح نافذة التنسيب.", "danger");
    }
}

// Warning modal when trying to enroll student already in another circle
function warnStudentInOtherCircle(studentName, circleName, teacherName) {
    const displayTeacher = teacherName && teacherName !== "غير محدد" ? teacherName : "معلم الحلقة";
    const displayCircle = circleName && circleName !== "غير مسند حلقة" ? circleName : "حلقة أخرى";
    
    if (typeof Swal !== "undefined") {
        Swal.fire({
            icon: "warning",
            title: "ممنوع تنسيب الطالب",
            html: `
                <div style="text-align: right; direction: rtl; font-size: 0.95rem; line-height: 1.8;">
                    <p class="mb-2">⚠️ <strong>ممنوع:</strong> الطالب <b>(${escapeXml(studentName)})</b> تم تنسيبه مسبقاً لحلقة <b>(${escapeXml(displayCircle)})</b>.</p>
                    <div class="alert alert-warning py-2 px-3 border my-2">
                        <i class="fa-solid fa-chalkboard-user me-1 text-warning"></i> الشيخ المعلم المسؤول: <strong>${escapeXml(displayTeacher)}</strong>
                    </div>
                    <p class="text-muted small mb-0">إذا كنت ترغب بنقل الطالب إلى حلقتك، يرجى التواصل والتنسيق مع فضيلة الشيخ <b>(${escapeXml(displayTeacher)})</b> أو مراجعة إدارة المركز.</p>
                </div>
            `,
            confirmButtonText: "حسناً، فهمت",
            confirmButtonColor: "#d97706"
        });
    } else {
        showAlert(`ممنوع: الطالب تم تنسيبه لحلقة أخرى (${displayCircle}). إذا كنت تريده تواصل مع المعلم (${displayTeacher}) أو إدارة المركز.`, "warning");
    }
}

// Execute the student enrollment into teacher's circle (Keeps modal open, updates immediately in background)
async function executeTeacherStudentEnrollment(studentId, studentName, btnElement) {
    const circleSelect = document.getElementById("teacher-enroll-target-circle");
    if (!circleSelect || !circleSelect.value) {
        showAlert("الرجاء اختيار الحلقة أولاً.", "warning");
        return;
    }
    const circleId = parseInt(circleSelect.value);
    const circleName = circleSelect.options[circleSelect.selectedIndex].text;

    // Check capacity client-side
    const maxCap = window.SYS_MAX_STUDENTS_CIRCLE || 20;
    const currentStudentsInTable = document.querySelectorAll("#teacher-students-table-body tr:not(.empty-row)").length;
    
    if (btnElement) {
        btnElement.disabled = true;
        btnElement.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-1"></i> جاري التنسيب...';
    }

    try {
        await apiRequest(`/circles/${circleId}/students`, "POST", { studentId: studentId });

        // Update button in-place to show success and prevent double click
        if (btnElement) {
            btnElement.className = "btn btn-outline-success btn-sm rounded-pill px-3 fw-bold flex-shrink-0";
            btnElement.innerHTML = '<i class="fa-solid fa-check me-1"></i> تم التنسيب بنجاح';
            btnElement.disabled = true;
        }

        // Show friendly alert/toast without closing the modal
        showAlert(`تم تنسيب الطالب (${studentName}) إلى حلقة (${circleName}) بنجاح! 🎉`, "success");

        // Refresh teacher views in the background immediately
        if (typeof loadTeacherStudentsTable === "function") loadTeacherStudentsTable();
        if (typeof loadAttendanceSheet === "function") loadAttendanceSheet();
        if (typeof loadAdminStudents === "function") loadAdminStudents();

        // Update student in memory if available
        const searchInput = document.getElementById("teacher-enroll-search-input");
        const footer = document.getElementById("teacher-enroll-capacity-footer");
        if (footer) {
            // Re-fetch or trigger capacity update
            setTimeout(() => {
                if (typeof loadTeacherStudentsTable === "function") loadTeacherStudentsTable();
            }, 300);
        }

    } catch (err) {
        console.error("Error enrolling student:", err);
        const errMsg = err && err.error ? err.error : (err.message || "تعذر إتمام عملية التنسيب.");
        showAlert(errMsg, "danger");

        // Restore button state on failure
        if (btnElement) {
            btnElement.disabled = false;
            btnElement.innerHTML = '<i class="fa-solid fa-plus me-1"></i> تنسيب لحلقتي';
        }
    }
}

// Unenroll student from circle
async function unenrollStudentFromCircle(studentId, studentName, circleId) {
    if (window.SYS_ALLOW_TEACHER_ENROLL === false) {
        showAlert("إلغاء تنسيب الطلاب معطل حالياً من إدارة المركز.", "warning");
        return;
    }

    const confirmed = await showConfirmModal(`هل أنت متأكد من فك ارتباط الطالب (${studentName}) من هذه الحلقة؟`);
    if (!confirmed) return;

    try {
        await apiRequest(`/circles/${circleId}/students/${studentId}`, "DELETE");
        showAlert(`تم فك ارتباط الطالب (${studentName}) من الحلقة بنجاح.`, "success");
        loadTeacherStudentsTable();
    } catch (e) {
        console.error("Error unenrolling student:", e);
        showAlert("تعذر فك ارتباط الطالب.", "danger");
    }
}

// Modal for Teacher to register a brand new student directly
async function showTeacherAddNewStudentModal() {
    if (window.SYS_ALLOW_TEACHER_ENROLL === false) {
        showAlert("تسجيل الطلاب الجدد بواسطة المعلم معطل حالياً من إدارة المركز.", "warning");
        return;
    }
    await showStudentModal();
}

