            healthStatus: health || null,
            fatherStatus: fatherStat || null,
            motherStatus: motherStat || null,
            kinship: kinship || null,
            parentIdentityNumber: pIdNum || null,
            whatsappNumber: whatsapp || null,
            walletNumber: wallet || null,
