// ==========================================
const DEFAULT_SYSTEM_SETTINGS = {
    centerName: "مركز البيان لتعليم القرآن الكريم وتدريس علومه",
    mosqueName: "مسجد علي بن أبي طالب",
    centerAddress: "فلسطين - غزة - المقر الرئيسي",
    supportPhone: "+970599000000",
    supportEmail: "info@albayan.quran",
    welcomeMessage: "أهلاً وسهلاً بكم في منصة مركز البيان لتعليم القرآن الكريم والعلوم الشرعية",
    passingScoreThreshold: 70,
    minAttendancePercentForExam: 75,
    maxStudentsPerCircle: 20,
    maxAbsenceDaysWarning: 3,
    allowTeacherEditStudentPlan: true,
    allowTeacherSelfEnrollment: true,
    hideParentPhoneFromTeacher: false,
    allowStudentProfileEditRequests: true,
    enforceDailyAttendanceRecording: true,
    showCumulativeAttendance: true,
    signatoryName: "فضيلة الشيخ / رئيس المركز",
    signatoryTitle: "المشرف العام على حلقات تحفيظ القرآن الكريم",
    enableCertificates: true,
    showHonorsBoard: true,
    allowPublicAnnouncements: true,
    enableAbsenceAutoAlert: true,
    absenceAlertTemplate: "نود إشعاركم بغياب الطالب/ة اليوم عن حلقة القرآن الكريم، نرجو المتابعة والتواصل مع إدارة المركز.",
    themeStyle: "Classic",
    maintenanceMode: false,
    logoUrl: ""
};

let cachedSystemSettings = null;

function toBoolean(val, defaultVal) {
    if (val === true || val === 1 || val === "true" || val === "1") return true;
    if (val === false || val === 0 || val === "false" || val === "0") return false;
    return defaultVal;
}

function cleanArabicText(val, fallback) {
    if (!val || typeof val !== 'string') return fallback;
    const trimmed = val.trim();
    if (!trimmed) return fallback;
    if (/^\?+$/.test(trimmed)) return fallback;
    return trimmed;
}

function normalizeSettings(s) {
    if (!s) return Object.assign({}, DEFAULT_SYSTEM_SETTINGS);
    return {
        centerName: cleanArabicText(s.centerName || s.CenterName, DEFAULT_SYSTEM_SETTINGS.centerName),
        mosqueName: cleanArabicText(s.mosqueName || s.MosqueName, DEFAULT_SYSTEM_SETTINGS.mosqueName),
        centerAddress: cleanArabicText(s.centerAddress || s.CenterAddress, DEFAULT_SYSTEM_SETTINGS.centerAddress),
        supportPhone: s.supportPhone || s.SupportPhone || DEFAULT_SYSTEM_SETTINGS.supportPhone,
        supportEmail: s.supportEmail || s.SupportEmail || DEFAULT_SYSTEM_SETTINGS.supportEmail,
        welcomeMessage: cleanArabicText(s.welcomeMessage || s.WelcomeMessage, DEFAULT_SYSTEM_SETTINGS.welcomeMessage),
        logoUrl: s.logoUrl || s.LogoUrl || "",
        themeStyle: s.themeStyle || s.ThemeStyle || DEFAULT_SYSTEM_SETTINGS.themeStyle,
        passingScoreThreshold: Number(s.passingScoreThreshold ?? s.PassingScoreThreshold ?? DEFAULT_SYSTEM_SETTINGS.passingScoreThreshold),
        minAttendancePercentForExam: Number(s.minAttendancePercentForExam ?? s.MinAttendancePercentForExam ?? DEFAULT_SYSTEM_SETTINGS.minAttendancePercentForExam),
        maxStudentsPerCircle: Number(s.maxStudentsPerCircle ?? s.MaxStudentsPerCircle ?? DEFAULT_SYSTEM_SETTINGS.maxStudentsPerCircle),
        maxAbsenceDaysWarning: Number(s.maxAbsenceDaysWarning ?? s.MaxAbsenceDaysWarning ?? DEFAULT_SYSTEM_SETTINGS.maxAbsenceDaysWarning),
        allowTeacherEditStudentPlan: toBoolean(s.allowTeacherEditStudentPlan ?? s.AllowTeacherEditStudentPlan, DEFAULT_SYSTEM_SETTINGS.allowTeacherEditStudentPlan),
        allowTeacherSelfEnrollment: toBoolean(s.allowTeacherSelfEnrollment ?? s.AllowTeacherSelfEnrollment, DEFAULT_SYSTEM_SETTINGS.allowTeacherSelfEnrollment),
        hideParentPhoneFromTeacher: toBoolean(s.hideParentPhoneFromTeacher ?? s.HideParentPhoneFromTeacher, DEFAULT_SYSTEM_SETTINGS.hideParentPhoneFromTeacher),
        allowStudentProfileEditRequests: toBoolean(s.allowStudentProfileEditRequests ?? s.AllowStudentProfileEditRequests, DEFAULT_SYSTEM_SETTINGS.allowStudentProfileEditRequests),
        enforceDailyAttendanceRecording: toBoolean(s.enforceDailyAttendanceRecording ?? s.EnforceDailyAttendanceRecording, DEFAULT_SYSTEM_SETTINGS.enforceDailyAttendanceRecording),
        showStudentCountToTeacher: toBoolean(s.showStudentCountToTeacher ?? s.ShowStudentCountToTeacher, DEFAULT_SYSTEM_SETTINGS.showStudentCountToTeacher),
        showCumulativeAttendance: toBoolean(s.showCumulativeAttendance ?? s.ShowCumulativeAttendance, DEFAULT_SYSTEM_SETTINGS.showCumulativeAttendance),
        enableCertificates: toBoolean(s.enableCertificates ?? s.EnableCertificates, DEFAULT_SYSTEM_SETTINGS.enableCertificates),
        signatoryName: cleanArabicText(s.signatoryName || s.SignatoryName, DEFAULT_SYSTEM_SETTINGS.signatoryName),
        signatoryTitle: cleanArabicText(s.signatoryTitle || s.SignatoryTitle, DEFAULT_SYSTEM_SETTINGS.signatoryTitle),
        showHonorsBoard: toBoolean(s.showHonorsBoard ?? s.ShowHonorsBoard, DEFAULT_SYSTEM_SETTINGS.showHonorsBoard),
        allowPublicAnnouncements: toBoolean(s.allowPublicAnnouncements ?? s.AllowPublicAnnouncements, DEFAULT_SYSTEM_SETTINGS.allowPublicAnnouncements),
        enableAbsenceAutoAlert: toBoolean(s.enableAbsenceAutoAlert ?? s.EnableAbsenceAutoAlert, DEFAULT_SYSTEM_SETTINGS.enableAbsenceAutoAlert),
        absenceAlertTemplate: cleanArabicText(s.absenceAlertTemplate || s.AbsenceAlertTemplate, DEFAULT_SYSTEM_SETTINGS.absenceAlertTemplate),
        maintenanceMode: toBoolean(s.maintenanceMode ?? s.MaintenanceMode, DEFAULT_SYSTEM_SETTINGS.maintenanceMode)
    };
}

async function fetchAndApplySystemSettings(silent = true) {
    // 1. Instant load from localStorage or default to prevent flicker
    try {
        const localSaved = localStorage.getItem("system_settings_cache");
        if (localSaved) {
            const parsed = JSON.parse(localSaved);
            cachedSystemSettings = normalizeSettings(parsed);
        } else {
            cachedSystemSettings = normalizeSettings(DEFAULT_SYSTEM_SETTINGS);
        }
        applySystemSettingsToUI(cachedSystemSettings);
    } catch(e) {
        cachedSystemSettings = normalizeSettings(DEFAULT_SYSTEM_SETTINGS);
        applySystemSettingsToUI(cachedSystemSettings);
    }

    // 2. Fetch fresh live settings from API with cross-browser cache-busting and seamless cloud failover
    try {
        const timestamp = Date.now();
        let response = null;
        try {
            response = await fetch(`${API_BASE}/settings?t=${timestamp}`, { cache: "no-store" });
        } catch(netErr) {
            if (isLocalEnv && API_BASE !== "https://albayan-ali-center.tryasp.net/api") {
                response = await fetch(`https://albayan-ali-center.tryasp.net/api/settings?t=${timestamp}`, { cache: "no-store" }).catch(() => null);
                if (response && response.ok) {
                    API_BASE = "https://albayan-ali-center.tryasp.net/api";
                }
            }
        }
        if ((!response || !response.ok) && isLocalEnv && API_BASE !== "https://albayan-ali-center.tryasp.net/api") {
            response = await fetch(`https://albayan-ali-center.tryasp.net/api/settings?t=${timestamp}`, { cache: "no-store" }).catch(() => null);
            if (response && response.ok) {
                API_BASE = "https://albayan-ali-center.tryasp.net/api";
            }
        }
        if (response && response.ok) {
            const settings = await response.json();
            cachedSystemSettings = normalizeSettings(settings);
            localStorage.setItem("system_settings_cache", JSON.stringify(cachedSystemSettings));
            applySystemSettingsToUI(cachedSystemSettings);
        }
    } catch(err) {
        // Silently use cached/default settings
    }
}

function applySystemSettingsToUI(rawSettings) {
    const settings = normalizeSettings(rawSettings);
    cachedSystemSettings = settings;

    // A. Update Browser Title
    if (settings.centerName) {
        document.title = `${settings.centerName} - نظام إدارة الحلقات القرآنيّة`;
    }

    // B. Update Center Name in Header, Login, and everywhere with dynamic classes
    const centerElements = document.querySelectorAll(".dynamic-center-name, #brand-header-center-name, #brand-login-center-name");
    centerElements.forEach(el => {
        if (settings.centerName) el.textContent = settings.centerName;
    });

    // C. Update Mosque Name
    const mosqueElements = document.querySelectorAll(".dynamic-mosque-name, #brand-header-mosque-name, #brand-login-mosque-name");
    mosqueElements.forEach(el => {
        if (settings.mosqueName) el.textContent = settings.mosqueName;
    });

    // D. Update Welcome Message / Slogan
    const welcomeElements = document.querySelectorAll(".dynamic-welcome-msg, #brand-login-welcome-msg");
    welcomeElements.forEach(el => {
        if (settings.welcomeMessage) el.textContent = settings.welcomeMessage;
    });

    // E. Update Dynamic Logo if provided
    if (settings.logoUrl && settings.logoUrl.trim().length > 10) {
        const logoElements = document.querySelectorAll("#brand-header-logo, #brand-login-logo, .dynamic-center-logo");
        logoElements.forEach(el => {
            el.src = settings.logoUrl;
        });
    }

    // F. Apply Dynamic Theme Style (Classic, Modern, Sapphire, Dark)
    document.body.classList.remove("theme-classic", "theme-modern", "theme-sapphire", "theme-dark");
    const themeClass = `theme-${(settings.themeStyle || 'classic').toLowerCase()}`;
    document.body.classList.add(themeClass);

    // G. Expose global constants for runtime validation in other modules
    window.SYS_SETTINGS = settings;
    window.SYS_PASSING_SCORE = Number(settings.passingScoreThreshold) || 70;
    window.SYS_MIN_ATTENDANCE_EXAM = Number(settings.minAttendancePercentForExam) || 75;
    window.SYS_MAX_STUDENTS_CIRCLE = Number(settings.maxStudentsPerCircle) || 20;
    window.SYS_MAX_ABSENCE_WARNING = Number(settings.maxAbsenceDaysWarning) || 3;
    window.SYS_ALLOW_TEACHER_ENROLL = settings.allowTeacherSelfEnrollment === true;
    window.SYS_ALLOW_TEACHER_EDIT_PLAN = settings.allowTeacherEditStudentPlan === true;
    window.SYS_HIDE_PARENT_PHONE = settings.hideParentPhoneFromTeacher === true;
    window.SYS_ALLOW_PROFILE_REQUESTS = settings.allowStudentProfileEditRequests === true;
    window.SYS_ENFORCE_DAILY_ATTENDANCE = settings.enforceDailyAttendanceRecording === true;
    window.SYS_ENABLE_CERTIFICATES = settings.enableCertificates === true;
    window.SYS_SIGNATORY_NAME = settings.signatoryName || 'فضيلة الشيخ / رئيس المركز';
    window.SYS_SIGNATORY_TITLE = settings.signatoryTitle || 'المشرف العام على حلقات تحفيظ القرآن الكريم';
    window.SYS_SHOW_HONORS_BOARD = settings.showHonorsBoard === true;
    window.SYS_ALLOW_PUBLIC_ANNOUNCEMENTS = settings.allowPublicAnnouncements === true;
    window.SYS_ENABLE_ABSENCE_ALERT = settings.enableAbsenceAutoAlert === true;
    window.SYS_ABSENCE_ALERT_TEMPLATE = settings.absenceAlertTemplate || '';

    // H. Immediate DOM element visibility synchronization across all views
    document.querySelectorAll(".teacher-enroll-action-btn, #btn-teacher-enroll-existing, #btn-teacher-add-new-student").forEach(el => {
        el.style.display = window.SYS_ALLOW_TEACHER_ENROLL ? "inline-flex" : "none";
    });

    const teacherStudentsNavSpan = document.querySelector("#btn-teacher-students span");
    if (teacherStudentsNavSpan) {
        teacherStudentsNavSpan.textContent = window.SYS_ALLOW_TEACHER_ENROLL ? "تنسيب وإدارة طلاب حلقاتي" : "إدارة طلاب حلقاتي";
    }

    document.querySelectorAll(".parent-edit-profile-btn, .btn-request-profile-edit").forEach(el => {
        el.style.display = window.SYS_ALLOW_PROFILE_REQUESTS ? "inline-flex" : "none";
    });
}

